## Method 2: Create a Color Loader Service

Create a new service to load pywal/matugen colors:

````qml
import QtQuick
import Quickshell

Singleton {
    id: colorLoader

    property var pywalColors: ({})
    property var matugenColors: ({})
    property bool useMatugen: true

    // Load pywal colors
    function loadPywalColors() {
        const pywalPath = Standards.paths.cache + "/wal/colors.json"
        try {
            const data = Quickshell.readFile(pywalPath)
            pywalColors = JSON.parse(data)
        } catch (e) {
            console.log("Failed to load pywal colors:", e)
        }
    }

    // Load matugen colors  
    function loadMatugenColors() {
        const matugenPath = Standards.paths.config + "/matugen/colors.json"
        try {
            const data = Quickshell.readFile(matugenPath)
            matugenColors = JSON.parse(data)
        } catch (e) {
            console.log("Failed to load matugen colors:", e)
        }
    }

    // Get current color scheme
    property var currentColors: useMatugen ? matugenColors : pywalColors

    Component.onCompleted: {
        loadPywalColors()
        loadMatugenColors()
    }
}
````

