 *                                         
 */

/*-----------IMPORTING MATUGEN COLORS----------*/
@import "colors.css";

* {
    font-size: 12px;
    font-family: GeistMono Nerd Font Propo;
    font-weight: bold;
}

window#waybar{
    all:unset;
}

.modules-left {
    padding: 7px;
    margin: 10px 0px 5px 10px;
    border-radius: 10px;
    background: alpha(@surface_container,.8);
    box-shadow: 0px 0px 3px alpha(@shadow, .4);
    border: 1px solid alpha(@outline_variant, .3);
}

.modules-center {
    padding: 7px;
    margin: 10px 0px 5px 0px;
    border-radius: 10px;
    background: alpha(@surface_container,.8);
    box-shadow: 0px 0px 3px alpha(@shadow, .4);
    border: 1px solid alpha(@outline_variant, .3);
}

.modules-right {
    padding: 7px;
    margin: 10px 10px 5px 0px;
    border-radius: 10px;
    background: alpha(@surface_container,.8);
    box-shadow: 0px 0px 3px alpha(@shadow, .4);
    border: 1px solid alpha(@outline_variant, .3);
}

tooltip {
    background: @surface_container_high;
    border: 2px solid @primary;
    border-radius: 12px;
    box-shadow: 0px 0px 5px alpha(@shadow, .5);
}

tooltip-label {
    color: @on_surface;
    padding: 5px;
}

/* Hover effects for interactive modules */
#clock:hover, 
#custom-pacman:hover, 
#custom-notification:hover,
#bluetooth:hover,
#network:hover,
#battery:hover, 
#cpu:hover,
#memory:hover,
#temperature:hover,
#tray:hover,
#custom-weather:hover,
#pulseaudio:hover,
#backlight:hover {
    transition: all .3s ease;
    color: @primary_fixed_dim;
    text-shadow: 0px 0px 2px @primary;
}

/* Notification */
#custom-notification {
    padding: 0px 5px;
    transition: all .3s ease;
    color: @secondary;
}

/* Clock - Primary accent */
#clock {
    padding: 0px 5px;
    color: @primary;
    transition: all .3s ease;
}

/* Package manager updates */
#custom-pacman {
    padding: 0px 5px;
    transition: all .3s ease;
    color: @tertiary;
}

/* Workspaces */
#workspaces {
    padding: 0px 5px;
}

#workspaces button {
    all: unset;
    padding: 0px 5px;
    color: alpha(@on_surface_variant, .4);
    transition: all .2s ease;
}

#workspaces button:hover {
    color: alpha(@primary, .7);
    border: none;
    text-shadow: 0px 0px 2px @primary_fixed_dim;
    transition: all .3s ease;
}

#workspaces button.active {
    color: @primary;
    border: none;
    text-shadow: 0px 0px 4px @primary_fixed_dim;
    background: alpha(@primary_container, .2);
    border-radius: 5px;
